    10→ *
    11→ * Usage: node run-eval.js <spec.yaml> [options]
    12→ *
    13→ * Arguments:
    14→ *   spec.yaml          Path to evaluation specification file
    15→ *
    16→ * Options:
    17→ *   --parallel N       Run N sessions in parallel (default: 2)
    18→ *   --sequential       Run variants sequentially
    19→ *   --output DIR       Output directory for results (default: ../results)
    20→ *   --timeout SECONDS  Timeout per session (default: 300)
    21→ *   --quiet            Suppress progress output
    22→ *   --dry-run          Validate spec without running sessions
    23→ *   --help             Show this help
    24→ */
    25→
    26→const fs = require('fs');
    27→const path = require('path');
    28→const { spawn } = require('child_process');
    29→const yaml = require('js-yaml');
    30→
    31→// Constants
    32→const DEFAULT_PARALLEL = 2;
    33→const DEFAULT_TIMEOUT = 300;
    34→const RESULTS_BASE = path.join(__dirname, '..', 'results');
    35→
    36→/**
    37→ * Parse command line arguments
    38→ * @param {string[]} args - Command line arguments (without node and script name)
    39→ * @returns {object} Parsed arguments object
    40→ */
    41→function parseArgs(args) {
    42→  const result = {
    43→    specPath: null,
    44→    parallel: DEFAULT_PARALLEL,
    45→    sequential: false,
    46→    outputDir: null,
    47→    timeout: DEFAULT_TIMEOUT,
    48→    quiet: false,
    49→    dryRun: false,
    50→    help: false
    51→  };
    52→
    53→  for (let i = 0; i < args.length; i++) {
    54→    const arg = args[i];
    55→
    56→    switch (arg) {
    57→      case '--help':
    58→      case '-h':
    59→        result.help = true;
    60→        break;
    61→
    62→      case '--parallel':
    63→        result.parallel = parseInt(args[++i], 10);
    64→        break;
    65→
    66→      case '--sequential':
    67→        result.sequential = true;
    68→        result.parallel = 1;
    69→        break;
    70→
    71→      case '--output':
    72→        result.outputDir = args[++i];
    73→        break;
    74→
    75→      case '--timeout':
    76→        result.timeout = parseInt(args[++i], 10);
    77→        break;
    78→
    79→      case '--quiet':
    80→        result.quiet = true;
    81→        break;
    82→
    83→      case '--dry-run':
    84→        result.dryRun = true;
    85→        break;
    86→
    87→      default:
    88→        // First positional argument is the spec path
    89→        if (!arg.startsWith('-') && !result.specPath) {
    90→          result.specPath = arg;
    91→        }
    92→        break;
    93→    }
    94→  }
    95→
    96→  return result;
    97→}
    98→
    99→/**
   100→ * Load and parse YAML specification file
   101→ * @param {string} specPath - Path to the YAML spec file
   102→ * @returns {object} Parsed specification object
   103→ * @throws {Error} If file not found or invalid YAML
   104→ */
   105→function loadSpec(specPath) {
   106→  if (!fs.existsSync(specPath)) {
   107→    throw new Error(`Spec file not found: ${specPath}`);
   108→  }
   109→
   110→  const content = fs.readFileSync(specPath, 'utf8');
   111→
   112→  try {
   113→    return yaml.load(content);
   114→  } catch (err) {
   115→    throw new Error(`Failed to parse YAML: ${err.message}`);
   116→  }
   117→}
   118→
   119→/**
   120→ * Validate specification has all required fields
   121→ * @param {object} spec - Parsed specification object
   122→ * @throws {Error} If required fields are missing
   123→ */
   124→function validateSpec(spec) {
   125→  if (!spec.name) {
   126→    throw new Error('Missing required field: name');
   127→  }
   128→
   129→  if (!spec.variants || !Array.isArray(spec.variants)) {
   130→    throw new Error('Missing required field: variants');
   131→  }
   132→
   133→  if (spec.variants.length === 0) {
   134→    throw new Error('variants array cannot be empty');
   135→  }
   136→
   137→  for (let i = 0; i < spec.variants.length; i++) {
   138→    const variant = spec.variants[i];
   139→    if (!variant.id) {
   140→      throw new Error(`Variant at index ${i} missing required field: id`);
   141→    }
   142→  }
   143→
   144→  if (!spec.binary_checks || !Array.isArray(spec.binary_checks)) {
   145→    throw new Error('Missing required field: binary_checks');
   146→  }
   147→
   148→  if (!spec.metrics || !Array.isArray(spec.metrics)) {
   149→    throw new Error('Missing required field: metrics');
   150→  }
   151→}
   152→
   153→/**
   154→ * Create results directory for eval output
   155→ * @param {string} evalName - Name of the evaluation
   156→ * @param {string} baseDir - Base results directory
   157→ * @param {string} [customDir] - Optional custom output directory
   158→ * @returns {string} Path to created directory
   159→ */
   160→function createResultsDir(evalName, baseDir, customDir = null) {
   161→  if (customDir) {
   162→    fs.mkdirSync(customDir, { recursive: true });
   163→    return customDir;
   164→  }
   165→
   166→  const timestamp = new Date().toISOString().split('T')[0];
   167→  const timeComponent = new Date().toISOString().split('T')[1].replace(/[:.]/g, '-').slice(0, 8);
   168→  const dirName = `${evalName}_${timestamp}_${timeComponent}`;
   169→  const fullPath = path.join(baseDir, dirName);
   170→
   171→  fs.mkdirSync(fullPath, { recursive: true });
   172→
   173→  return fullPath;
   174→}
   175→
   176→/**
   177→ * Report progress to stderr
   178→ * @param {string} evalName - Name of the evaluation
   179→ * @param {string} message - Progress message
   180→ * @param {object} options - Options including quiet mode and progress info
   181→ */
   182→function reportProgress(evalName, message, options = {}) {
   183→  if (options.quiet) {
   184→    return;
   185→  }
   186→
   187→  let output = `[${evalName}] ${message}`;
   188→
   189→  if (options.current !== undefined && options.total !== undefined) {
   190→    output = `[${evalName}] ${message} (${options.current}/${options.total})`;
   191→  }
   192→
   193→  console.error(output);
   194→}
   195→
   196→/**
   197→ * Launch a single session
   198→ * @param {object} variant - Variant configuration
   199→ * @param {string} outputDir - Output directory path
   200→ * @param {number} timeout - Session timeout in seconds
   201→ * @returns {Promise<object>} Session result with session_id and exit status
   202→ */
   203→function launchSession(variant, outputDir, timeout) {
   204→  return new Promise((resolve, reject) => {
   205→    const sessionDir = path.join(outputDir, variant.id);
   206→    fs.mkdirSync(sessionDir, { recursive: true });
   207→
   208→    const runSessionPath = path.join(__dirname, 'run-session.sh');
   209→
   210→    // SECURITY: Verify script exists before attempting spawn
   211→    if (!fs.existsSync(runSessionPath)) {
   212→      return resolve({
   213→        variant_id: variant.id,
   214→        session_id: null,
   215→        exit_code: 1,
   216→        error: `Script not found: ${runSessionPath}`
   217→      });
   218→    }
   219→
   220→    const proc = spawn(runSessionPath, [variant.id, sessionDir], {
   221→      timeout: timeout * 1000
   222→    });
   223→
   224→    let sessionId = '';
   225→    let stderr = '';
   226→
   227→    proc.stdout.on('data', (data) => {
   228→      sessionId += data.toString().trim();
   229→    });
   230→
   231→    proc.stderr.on('data', (data) => {
   232→      stderr += data.toString();
   233→    });
   234→
   235→    proc.on('close', (code) => {
   236→      resolve({
   237→        variant_id: variant.id,
   238→        session_id: sessionId || null,
   239→        exit_code: code,
   240→        error: code !== 0 ? stderr : null
   241→      });
   242→    });
   243→
   244→    proc.on('error', (err) => {
   245→      // Handle spawn errors (ENOENT, EACCES, etc.)
   246→      resolve({
   247→        variant_id: variant.id,
   248→        session_id: null,
   249→        exit_code: 1,
   250→        error: `Spawn error: ${err.message} (code: ${err.code || 'unknown'})`
   251→      });
   252→    });
   253→  });
   254→}
   255→
   256→/**
   257→ * Launch sessions for all variants with parallel execution control
   258→ * @param {object} spec - Evaluation specification
   259→ * @param {string} outputDir - Output directory path
   260→ * @param {object} options - Options including parallel count
   261→ * @returns {Promise<object[]>} Array of session results
   262→ */
   263→async function launchSessions(spec, outputDir, options = {}) {
   264→  const parallel = options.parallel || DEFAULT_PARALLEL;
   265→  const timeout = options.timeout || DEFAULT_TIMEOUT;
   266→  const results = [];
   267→
   268→  // Create queue of variants to process
   269→  const queue = [...spec.variants];
   270→
   271→  // Process in batches based on parallel limit
   272→  while (queue.length > 0) {
   273→    const batch = queue.splice(0, parallel);
   274→
   275→    const batchResults = await Promise.all(
   276→      batch.map((variant) => launchSession(variant, outputDir, timeout))
   277→    );
   278→
   279→    results.push(...batchResults);
   280→  }
   281→
   282→  return results;
   283→}
