   285→/**
   286→ * Show help message
   287→ */
   288→function showHelp() {
   289→  console.log(`Usage: node run-eval.js <spec.yaml> [options]
   290→
   291→Arguments:
   292→  spec.yaml          Path to evaluation specification file
   293→
   294→Options:
   295→  --parallel N       Run N sessions in parallel (default: ${DEFAULT_PARALLEL})
   296→  --sequential       Run variants sequentially (same as --parallel 1)
   297→  --output DIR       Output directory for results (default: ../results/<name>_<timestamp>)
   298→  --timeout SECONDS  Timeout per session in seconds (default: ${DEFAULT_TIMEOUT})
   299→  --quiet            Suppress progress output
   300→  --dry-run          Validate spec without running sessions
   301→  --help             Show this help
