   397→    }
   398→  }
   399→
   400→  return scores;
   401→}
   402→
   403→/**
   404→ * Aggregate scores by variant
   405→ * @param {object} collectedScores - Collected scores from collectScores
   406→ * @returns {object} Aggregated statistics per variant
   407→ */
   408→function aggregateByVariant(collectedScores) {
   409→  const aggregated = {};
   410→
   411→  for (const [variant, data] of Object.entries(collectedScores)) {
   412→    const sessions = data.sessions;
   413→    const allScores = [];
   414→    const byRubric = {};
   415→    const rawScores = [];
   416→
   417→    for (const session of sessions) {
   418→      const sessionScores = Object.values(session.scores);
   419→      const sessionMean = sessionScores.reduce((a, b) => a + b, 0) / sessionScores.length;
   420→      allScores.push(sessionMean);
   421→      rawScores.push(sessionMean);
   422→
   423→      // Collect per-rubric scores
   424→      for (const [rubric, score] of Object.entries(session.scores)) {
   425→        if (!byRubric[rubric]) {
   426→          byRubric[rubric] = [];
   427→        }
   428→        byRubric[rubric].push(score);
   429→      }
   430→    }
   431→
   432→    // Calculate overall statistics
   433→    const overall = calculateStatistics(allScores);
   434→
   435→    // Calculate per-rubric statistics
   436→    const rubricStats = {};
   437→    for (const [rubric, scores] of Object.entries(byRubric)) {
   438→      rubricStats[rubric] = calculateStatistics(scores);
   439→    }
   440→
   441→    aggregated[variant] = {
   442→      sessions: sessions.length,
   443→      overall,
   444→      by_rubric: rubricStats,
   445→      raw_scores: rawScores,
   446→      raw_sessions: sessions
   447→    };
   448→  }
   449→
   450→  return aggregated;
   451→}
   452→
   453→/**
   454→ * Compare two variants statistically
   455→ * @param {object} aggregated - Aggregated statistics
   456→ * @param {number} [significanceLevel=0.05] - p-value threshold
   457→ * @returns {object|null} Comparison results or null if only one variant
   458→ */
   459→function compareVariants(aggregated, significanceLevel = 0.05) {
   460→  const variants = Object.keys(aggregated);
   461→
   462→  if (variants.length < 2) {
   463→    return null;
   464→  }
   465→
   466→  // Assume comparison between first two variants (with-skill vs without-skill)
   467→  // Convention: with-skill is the treatment, without-skill is the control
   468→  const treatment = variants.find((v) => v.includes('with')) || variants[0];
   469→  const control = variants.find((v) => v.includes('without')) || variants[1];
   470→
   471→  const treatmentData = aggregated[treatment];
   472→  const controlData = aggregated[control];
   473→
   474→  const difference = treatmentData.overall.mean - controlData.overall.mean;
   475→  const percentImprovement =
   476→    controlData.overall.mean > 0 ? (difference / controlData.overall.mean) * 100 : 0;
   477→
   478→  // Perform t-test if we have raw scores
   479→  let pValue = 1;
   480→  let significant = false;
   481→
   482→  if (treatmentData.raw_scores && controlData.raw_scores) {
   483→    const testResult = tTest(treatmentData.raw_scores, controlData.raw_scores);
   484→    pValue = testResult.p;
   485→    significant = pValue < significanceLevel;
   486→  }
   487→
   488→  return {
   489→    treatment,
   490→    control,
   491→    difference: parseFloat(difference.toFixed(2)),
   492→    percent_improvement: parseFloat(percentImprovement.toFixed(1)),
   493→    p_value: pValue,
   494→    significant
   495→  };
   496→}
   497→
   498→/**
   499→ * Generate markdown report from aggregated data
   500→ * @param {object} data - Report data
   501→ * @returns {string} Markdown report content
   502→ */
   503→function generateMarkdownReport(data) {
   504→  const lines = [];
   505→
   506→  lines.push(`# Evaluation Report: ${data.eval_name}`);
   507→  lines.push('');
   508→
   509→  // Summary section
   510→  lines.push('## Summary');
   511→  lines.push('');
   512→  lines.push('| Variant | Sessions | Mean Score | Std Dev |');
   513→  lines.push('|---------|----------|------------|---------|');
   514→
   515→  for (const [variant, stats] of Object.entries(data.variants)) {
   516→    const mean = stats.overall?.mean ?? 'N/A';
   517→    const stddev = stats.overall?.stddev ?? 'N/A';
   518→    lines.push(`| ${variant} | ${stats.sessions} | ${mean} | ${stddev} |`);
   519→  }
   520→  lines.push('');
   521→
   522→  // Comparison section
   523→  if (data.comparison) {
   524→    const c = data.comparison;
   525→    const direction = c.difference >= 0 ? '+' : '';
   526→    const significanceText = c.significant
   527→      ? `Statistically significant (p < ${c.p_value?.toFixed(3) || '0.05'})`
   528→      : `Not statistically significant (p = ${c.p_value?.toFixed(3) || 'N/A'})`;
   529→
   530→    lines.push(
   531→      `**Difference**: ${direction}${c.difference} points (${c.percent_improvement}% improvement) - ${significanceText}`
   532→    );
   533→    lines.push('');
   534→  }
   535→
   536→  // Per-rubric analysis
   537→  const rubrics = new Set();
   538→  for (const stats of Object.values(data.variants)) {
   539→    if (stats.by_rubric) {
   540→      Object.keys(stats.by_rubric).forEach((r) => rubrics.add(r));
   541→    }
   542→  }
   543→
   544→  if (rubrics.size > 0) {
   545→    lines.push('## Per-Rubric Analysis');
   546→    lines.push('');
   547→
   548→    for (const rubric of rubrics) {
   549→      lines.push(`### ${rubric}`);
   550→      lines.push('');
   551→      lines.push('| Variant | Mean | Median | Min | Max |');
   552→      lines.push('|---------|------|--------|-----|-----|');
   553→
   554→      for (const [variant, stats] of Object.entries(data.variants)) {
   555→        const rubricStats = stats.by_rubric?.[rubric];
   556→        if (rubricStats) {
   557→          lines.push(
   558→            `| ${variant} | ${rubricStats.mean} | ${rubricStats.median} | ${rubricStats.min} | ${rubricStats.max} |`
   559→          );
   560→        }
   561→      }
   562→      lines.push('');
   563→    }
   564→  }
   565→
   566→  // Raw scores section
   567→  lines.push('## Raw Scores');
   568→  lines.push('');
   569→
   570→  for (const [variant, stats] of Object.entries(data.variants)) {
   571→    lines.push(`### ${variant}`);
   572→    lines.push('');
   573→
   574→    if (stats.raw_sessions && stats.raw_sessions.length > 0) {
   575→      // Build header with all rubric columns
   576→      const rubricColumns = new Set();
   577→      for (const session of stats.raw_sessions) {
   578→        Object.keys(session.scores).forEach((r) => rubricColumns.add(r));
   579→      }
   580→
   581→      const headers = ['Session', ...rubricColumns];
   582→      lines.push('| ' + headers.join(' | ') + ' |');
   583→      lines.push('| ' + headers.map(() => '---').join(' | ') + ' |');
   584→
   585→      for (const session of stats.raw_sessions) {
   586→        const row = [session.sessionId];
   587→        for (const rubric of rubricColumns) {
   588→          row.push(session.scores[rubric] ?? '-');
   589→        }
   590→        lines.push('| ' + row.join(' | ') + ' |');
   591→      }
   592→    } else {
   593→      lines.push('No session data available.');
   594→    }
   595→    lines.push('');
   596→  }
   597→
   598→  // Methodology section
   599→  lines.push('## Methodology');
   600→  lines.push('');
   601→
   602→  if (data.methodology) {
   603→    if (data.methodology.model) {
   604→      lines.push(`- Model: ${data.methodology.model}`);
   605→    }
   606→    if (data.methodology.rubrics) {
   607→      lines.push(`- Rubrics: ${data.methodology.rubrics.join(', ')}`);
   608→    }
   609→  }
   610→
   611→  const sessionsPerVariant = Object.values(data.variants)[0]?.sessions || 'N/A';
   612→  lines.push(`- Sessions per variant: ${sessionsPerVariant}`);
   613→
   614→  if (data.generated_at) {
   615→    lines.push(`- Generated: ${data.generated_at}`);
   616→  }
   617→
   618→  lines.push('');
   619→
   620→  return lines.join('\n');
   621→}
   622→
   623→/**
   624→ * Generate JSON output from aggregated data
   625→ * @param {object} data - Report data
   626→ * @returns {string} JSON string
   627→ */
   628→function generateJsonOutput(data) {
   629→  const output = {
   630→    eval_name: data.eval_name,
   631→    generated_at: data.generated_at || new Date().toISOString(),
   632→    variants: {},
   633→    comparison: data.comparison || null
   634→  };
   635→
   636→  for (const [variant, stats] of Object.entries(data.variants)) {
   637→    output.variants[variant] = {
   638→      sessions: stats.sessions,
   639→      overall: stats.overall,
   640→      by_rubric: stats.by_rubric
   641→    };
   642→  }
   643→
   644→  // Include raw scores
   645→  const rawScores = {};
   646→  for (const [variant, stats] of Object.entries(data.variants)) {
   647→    if (stats.raw_sessions) {
   648→      rawScores[variant] = stats.raw_sessions.map((s) => ({
   649→        session: s.sessionId,
   650→        scores: s.scores
   651→      }));
   652→    }
   653→  }
   654→  if (Object.keys(rawScores).length > 0) {
   655→    output.raw_scores = rawScores;
   656→  }
   657→
   658→  return JSON.stringify(output, null, 2);
   659→}
   660→
   661→/**
   662→ * Report progress to stderr
   663→ * @param {string} message - Progress message
   664→ * @param {object} options - Options including quiet mode
   665→ */
   666→function reportProgress(message, options = {}) {
   667→  if (options.quiet) {
   668→    return;
   669→  }
   670→  console.error(`[aggregate] ${message}`);
   671→}
   672→
   673→/**
   674→ * Show help message
   675→ */
   676→function showHelp() {
   677→  console.log(`Usage: node aggregate.js [options] <eval-results-dir>
   678→
   679→Arguments:
   680→  eval-results-dir   Directory containing eval results (from run-eval.js)
   681→
   682→Options:
   683→  --output FILE      Output report file (default: <eval-results-dir>/report.md)
   684→  --format FORMAT    Output format: markdown, json, both (default: markdown)
   685→  --significance N   p-value threshold for highlighting (default: 0.05)
   686→  --quiet            Suppress progress output
   687→  --help             Show this help
   688→
   689→Examples:
   690→  node aggregate.js results/my-eval-2026-01-13/
   691→  node aggregate.js results/python-skill/ --format json
   692→  node aggregate.js results/test/ --output custom-report.md --format both`);
   693→}
   694→
   695→/**
   696→ * Main run function
   697→ * @param {string[]} args - Command line arguments
   698→ * @returns {Promise<object>} Result object with exitCode and optional error
   699→ */
   700→async function run(args) {
   701→  const parsedArgs = parseArgs(args);
   702→
   703→  // Handle help
   704→  if (parsedArgs.help) {
   705→    showHelp();
   706→    return { exitCode: 0 };
   707→  }
   708→
   709→  // Validate results directory provided
   710→  if (!parsedArgs.resultsDir) {
   711→    return {
   712→      exitCode: 1,
   713→      error: 'Error: eval results directory argument is required\n\nRun with --help for usage information.'
   714→    };
   715→  }
   716→
   717→  // Check results directory exists
   718→  if (!fs.existsSync(parsedArgs.resultsDir)) {
   719→    return {
   720→      exitCode: 1,
   721→      error: `Error: Results directory not found: ${parsedArgs.resultsDir}`
   722→    };
   723→  }
   724→
   725→  reportProgress(`Collecting scores from ${parsedArgs.resultsDir}`, parsedArgs);
   726→
   727→  // Collect and aggregate scores
   728→  const collectedScores = collectScores(parsedArgs.resultsDir);
   729→  const aggregated = aggregateByVariant(collectedScores);
   730→
   731→  reportProgress(`Found ${Object.keys(aggregated).length} variants`, parsedArgs);
   732→
   733→  // Compare variants
   734→  const comparison = compareVariants(aggregated, parsedArgs.significance);
   735→
   736→  // Try to get eval name from sessions.json
   737→  let evalName = path.basename(parsedArgs.resultsDir);
   738→  const sessionsPath = path.join(parsedArgs.resultsDir, 'sessions.json');
   739→  if (fs.existsSync(sessionsPath)) {
   740→    try {
   741→      const sessions = JSON.parse(fs.readFileSync(sessionsPath, 'utf8'));
   742→      evalName = sessions.evalName || evalName;
   743→    } catch (err) {
   744→      // Use directory name as fallback
   745→    }
   746→  }
   747→
   748→  // Get all rubrics for methodology
   749→  const allRubrics = new Set();
   750→  for (const stats of Object.values(aggregated)) {
   751→    if (stats.by_rubric) {
   752→      Object.keys(stats.by_rubric).forEach((r) => allRubrics.add(r));
   753→    }
   754→  }
   755→
   756→  // Build report data
   757→  const reportData = {
   758→    eval_name: evalName,
   759→    generated_at: new Date().toISOString(),
   760→    variants: aggregated,
   761→    comparison,
   762→    methodology: {
   763→      model: 'claude-opus-4-5-20251101',
   764→      rubrics: Array.from(allRubrics)
   765→    }
   766→  };
   767→
   768→  // Generate and write output
   769→  const baseOutput = parsedArgs.output || path.join(parsedArgs.resultsDir, 'report');
   770→
   771→  if (parsedArgs.format === 'markdown' || parsedArgs.format === 'both') {
   772→    const mdPath = parsedArgs.output || `${baseOutput}.md`;
   773→    const markdown = generateMarkdownReport(reportData);
   774→    fs.writeFileSync(mdPath, markdown);
   775→    reportProgress(`Wrote markdown report: ${mdPath}`, parsedArgs);
   776→  }
   777→
   778→  if (parsedArgs.format === 'json' || parsedArgs.format === 'both') {
   779→    const jsonPath = parsedArgs.output
   780→      ? parsedArgs.output.replace(/\.md$/, '.json')
   781→      : `${baseOutput}.json`;
   782→    const json = generateJsonOutput(reportData);
   783→    fs.writeFileSync(jsonPath, json);
   784→    reportProgress(`Wrote JSON report: ${jsonPath}`, parsedArgs);
   785→  }
   786→
   787→  reportProgress('Aggregation complete', parsedArgs);
   788→
   789→  return { exitCode: 0 };
   790→}
   791→
   792→// Main entry point when run directly
   793→if (require.main === module) {
   794→  run(process.argv.slice(2))
   795→    .then((result) => {
   796→      if (result.error) {
   797→        console.error(result.error);
   798→      }
   799→      process.exit(result.exitCode);
   800→    })
   801→    .catch((err) => {
   802→      console.error(`Unexpected error: ${err.message}`);
   803→      process.exit(1);
   804→    });
   805→}
   806→
   807→// Export for testing
   808→module.exports = {
   809→  parseArgs,
   810→  calculateStatistics,
   811→  collectScores,
   812→  aggregateByVariant,
   813→  compareVariants,
   814→  generateMarkdownReport,
   815→  generateJsonOutput,
   816→  tTest,
