/**
 * Collect scores from eval results directory
 * @param {string} resultsDir - Path to results directory
 * @returns {object} Collected scores grouped by variant
 */
function collectScores(resultsDir) {
  const scores = {};

  // Get list of variant directories
  const entries = fs.readdirSync(resultsDir);

  for (const entry of entries) {
    const variantPath = path.join(resultsDir, entry);

    // Skip non-directories and special files
    if (!fs.statSync(variantPath).isDirectory()) {
      continue;
    }

    // Skip metadata files
    if (entry === 'sessions.json' || entry.startsWith('.')) {
      continue;
    }

    scores[entry] = {
      sessions: []
    };

    // Get session directories within variant
    let sessionDirs;
    try {
      sessionDirs = fs.readdirSync(variantPath);
    } catch (err) {
      continue;
    }

    for (const sessionDir of sessionDirs) {
      const sessionPath = path.join(variantPath, sessionDir);

      if (!fs.statSync(sessionPath).isDirectory()) {
        continue;
      }

      // Look for score.json in session directory
      const scorePath = path.join(sessionPath, 'score.json');

      if (!fs.existsSync(scorePath)) {
        continue;
      }

      try {
        const scoreData = JSON.parse(fs.readFileSync(scorePath, 'utf8'));
        const sessionScores = {};

        // Validate required structure
        if (!scoreData || typeof scoreData !== 'object') {
          logWarning(`Malformed score file (not an object): ${scorePath}`);
          continue;
        }

        if (!Array.isArray(scoreData.scores)) {
          // Handle both array and single object formats
          if (scoreData.scores && typeof scoreData.scores === 'object') {
            // Single score object format - try to extract
            if (typeof scoreData.scores.overall === 'number') {
              sessionScores['overall'] = scoreData.scores.overall;
            } else {
              logWarning(`Score file has scores object but no valid scores: ${scorePath}`);
              continue;
            }
          } else {
            logWarning(`Score file missing 'scores' array: ${scorePath}`);
            continue;
          }
        } else {
          for (const scoreEntry of scoreData.scores) {
            // Validate each score entry
            if (!scoreEntry || typeof scoreEntry !== 'object') {
              logWarning(`Invalid score entry (not an object) in ${scorePath}`);
              continue;
            }
            if (typeof scoreEntry.rubric !== 'string' || !scoreEntry.rubric) {
              logWarning(`Score entry missing rubric field in ${scorePath}`);
              continue;
            }
            if (typeof scoreEntry.score !== 'number') {
              logWarning(`Score entry has non-numeric score for "${scoreEntry.rubric}" in ${scorePath}`);
              continue;
            }
            if (scoreEntry.score < 1 || scoreEntry.score > 5) {
              logWarning(`Score out of range (${scoreEntry.score}) for "${scoreEntry.rubric}" in ${scorePath}`);
            }
            sessionScores[scoreEntry.rubric] = scoreEntry.score;
          }
        }

        if (Object.keys(sessionScores).length === 0) {
          logWarning(`No valid scores extracted from: ${scorePath}`);
          continue;
        }

        scores[entry].sessions.push({
          sessionId: sessionDir,
          scores: sessionScores,
          raw: scoreData.scores
        });
      } catch (err) {
        logWarning(`Failed to parse score file ${scorePath}: ${err.message}`);
        continue;
      }
    }
  }

  return scores;
}

