  run(process.argv.slice(2))
    .then((result) => {
      if (result.error) {
        console.error(result.error);
      }
      process.exit(result.exit_code);
    })
    .catch((err) => {
      console.error(`Unexpected error: ${err.message}`);
      process.exit(1);
    });
}

// Export for testing
module.exports = {
  parseArgs,
  loadSpec,
  validateSpec,
  createResultsDir,
  launchSession,
  launchSessions,
  reportProgress,
  run
};

