  let outputDir;
  try {
    outputDir = createResultsDir(spec.name, RESULTS_BASE, parsedArgs.outputDir);
  } catch (err) {
    return {
      exit_code: 1,
      error: `Error creating output directory: ${err.message}`
    };
  }

