  if (parsedArgs.dryRun) {
    printDryRunReport(spec, outputDir, parsedArgs);
    return { exit_code: 0 };
  }

  // Report start
  reportProgress(spec.name, 'Starting evaluation', parsedArgs);
  reportProgress(spec.name, `Output: ${outputDir}`, parsedArgs);

  // Launch sessions
  reportProgress(spec.name, `Launching ${spec.variants.length} variant sessions`, parsedArgs);

  const sessions = await launchSessions(spec, outputDir, {
    parallel: parsedArgs.parallel,
    timeout: parsedArgs.timeout
  });

  // Report results and log failures
  let hasFailures = false;
  sessions.forEach((session) => {
    if (session.exit_code !== 0) {
      hasFailures = true;
      reportProgress(spec.name, `Warning: ${session.variant_id} failed: ${session.error}`, parsedArgs);
    } else {
      reportProgress(spec.name, `Completed: ${session.variant_id}`, parsedArgs);
    }
  });

