const fs = require('fs');
const path = require('path');
const { spawn, spawnSync } = require('child_process');
const yaml = require('js-yaml');

// Constants
const DEFAULT_PARALLEL = 2;
const DEFAULT_TIMEOUT = 300;
const RESULTS_BASE = path.join(__dirname, '..', 'results');

/**
 * Parse command line arguments
 * @param {string[]} args - Command line arguments (without node and script name)
 * @returns {object} Parsed arguments object
 */
function parseArgs(args) {
  const result = {
    specPath: null,
    parallel: DEFAULT_PARALLEL,
    sequential: false,
    outputDir: null,
    timeout: DEFAULT_TIMEOUT,
    quiet: false,
    dryRun: false,
    help: false
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    switch (arg) {
      case '--help':
      case '-h':
        result.help = true;
        break;

      case '--parallel':
        result.parallel = parseInt(args[++i], 10);
        break;

      case '--sequential':
        result.sequential = true;
        result.parallel = 1;
        break;

      case '--output':
        result.outputDir = args[++i];
        break;

      case '--timeout':
        result.timeout = parseInt(args[++i], 10);
        break;

      case '--quiet':
        result.quiet = true;
        break;

      case '--dry-run':
        result.dryRun = true;
        break;

      default:
        // First positional argument is the spec path
        if (!arg.startsWith('-') && !result.specPath) {
          result.specPath = arg;
        }
        break;
    }
  }

  return result;
